// Cycle through the cells in the bucket, starting at a random position.
// The randomness avoids worst-case search overhead as buckets fill up.
unsigned offset = static_cast<unsigned>(prng_lg_range_u64(&ckh->prng_state, LG_CKH_BUCKET_CELLS));
for (unsigned i = 0; i < (ZU(1) << LG_CKH_BUCKET_CELLS); i++) {
    ckhc_t* cell = &ckh->tab[(bucket << LG_CKH_BUCKET_CELLS) + ((i + offset) & ((ZU(1) << LG_CKH_BUCKET_CELLS) - 1))];
    if (cell->key == nullptr) {
        cell->key = key;
        cell->data = data;
        ckh->count++;
        return false;
    }
}
return true;

